$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$out=Join-Path $root '.cache/validation/comp-req-558-ota-host';New-Item -ItemType Directory -Force $out|Out-Null
$vc=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio/2022/BuildTools/VC/Auxiliary/Build/vcvars64.bat';if(!(Test-Path $vc)){throw 'MSVC unavailable'}
$exe=Join-Path $out 'comp-req-558-ota-host.exe';if(Test-Path $exe){Remove-Item -LiteralPath $exe -Force}
$inc='/I"'+(Join-Path $root 'third_party/denzic-platform/ota/embedded/c/include')+'"';$src='"'+(Join-Path $root 'tools/comp_req_558_ota_host.c')+'" "'+(Join-Path $root 'third_party/denzic-platform/ota/embedded/c/src/denzic_ota_v1.c')+'"';$cmd='call "'+$vc+'" >nul && cl.exe /nologo /Brepro /TC /std:c11 /O2 /W4 /WX /wd4295 '+$inc+' '+$src+' /Fe:"'+$exe+'"';$log=Join-Path $out 'compile.log';cmd /d /s /c $cmd *> $log;$compileExit=$LASTEXITCODE;if($compileExit-ne0){throw "OTA compile failed: $compileExit"};$stdout=(& $exe 2>&1|Out-String).Trim();$runExit=$LASTEXITCODE;$r=[ordered]@{schema='companion.comp_req_558.ota.host.v1';status=if($runExit-eq0){'PASS'}else{'NO_GO'};compile_exit=$compileExit;run_exit=$runExit;compile_command=$cmd;compile_log_sha256=(Get-FileHash $log -Algorithm SHA256).Hash.ToUpper();executable_sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToUpper();stdout=$stdout;stdout_sha256=[BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash([Text.Encoding]::UTF8.GetBytes($stdout))).Replace('-','')};$r|ConvertTo-Json -Depth 8|Set-Content -Encoding utf8 (Join-Path $out 'result.json');if($runExit-ne0){exit $runExit}
